from lcsgo import *
subject('go', 'Go', 'go', 'lang', 'Language-specific practice: fmt.Scan input, slices and maps, strings and runes, structs and interfaces, goroutines and algorithms.')
Ag = ar(-9, 20, 1, 10)
topic('goio', 'Basics and fmt', 'fmt.Scan, fmt.Printf verbs, types, for loops, switch and constants')
Q('Easy', 'Add Two Ints', 'Read two ints with fmt.Scan and print the sum. | Input: two integers. | Output: sum.', lambda s: sum(iv(s)), [L('3 4')], two(-1000, 1000))
Q('Easy', 'Printf Float', 'Print with fmt.Printf("%.2f\\n"). | Input: real number. | Output: two decimals.', lambda s: '%.2f' % float(s), [L('3.14159')], lambda r: L(round(r.uniform(-100, 100), 4)))
Q('Easy', 'Even Or Odd', 'Print even or odd. | Input: N. | Output: even/odd.', lambda s: 'even' if int(s) % 2 == 0 else 'odd', [L(3)], num(-50, 50))
Q('Easy', 'Max Of Three', 'Print the largest. | Input: three integers. | Output: largest.', lambda s: max(iv(s)), [L('3 9 2')], lambda r: L(J([r.randint(-50, 50) for _ in range(3)])))
Q('Easy', 'Sum To N', 'Loop 1..N. | Input: N. | Output: sum.', lambda s: sum(range(1, int(s) + 1)), [L(10)], num(1, 1000))
Q('Easy', 'Swap With Tuple', 'Swap a and b with a, b = b, a. | Input: a b. | Output: "b a".', lambda s: '%d %d' % tuple(iv(s)[::-1]), [L('1 2')], two(-50, 50))
Q('Easy', 'Printf Verbs', 'Print "%d in hex is %x" for N. | Input: N. | Output: sentence.', lambda s: '%d in hex is %x' % (int(s), int(s)), [L(255)], num(0, 100000))
Q('Medium', 'Switch Grade', 'switch with no tag for grade A/B/C/F. | Input: mark. | Output: letter.', lambda s: (lambda m: 'A' if m >= 90 else 'B' if m >= 75 else 'C' if m >= 50 else 'F')(int(s)), [L(80)], num(0, 100))
Q('Medium', 'Leap Year', 'Print true or false. | Input: year. | Output: true/false.', lambda s: 'true' if (lambda y: y % 4 == 0 and (y % 100 != 0 or y % 400 == 0))(int(s)) else 'false', [L(2000)], num(1, 3000))
Q('Medium', 'Digit Sum', 'Digit sum of |N|. | Input: N. | Output: sum.', lambda s: ds(int(s)), [L(-4321)], num(-99999, 99999))
Q('Medium', 'Prime Check', 'Print prime or composite (0 and 1 composite). | Input: N. | Output: word.', lambda s: 'prime' if isp(int(s)) else 'composite', [L(7)], num(0, 5000))
Q('Medium', 'Read Until EOF', 'Loop on fmt.Scan until error; print count and sum. | Input: integers on any lines. | Output: "count sum".', lambda s: '%d %d' % (len(s.split()), sum(map(int, s.split()))), [L('1 2', '3')], lambda r: L(*[J([r.randint(-9, 9) for _ in range(r.randint(1, 4))]) for _ in range(r.randint(1, 3))]))
Q('Medium', 'Multiple Return Divmod', 'Function returning quotient and remainder. | Input: a b (b>0). | Output: "q r".', lambda s: '%d %d' % divmod(*iv(s)), [L('17 5')], lambda r: L('%d %d' % (r.randint(0, 300), r.randint(1, 20))))
Q('Medium', 'Multiplication Table', '"N x i = v" i=1..10. | Input: N. | Output: 10 lines.', lambda s: '\n'.join('%d x %d = %d' % (int(s), i, int(s) * i) for i in range(1, 11)), [L(3)], num(1, 30))
Q('Medium', 'Overflow int64', 'Multiply two numbers up to 10^9 in int64. | Input: a b. | Output: product.', lambda s: iv(s)[0] * iv(s)[1], [L('1000000000 1000000000')], lambda r: L('%d %d' % (r.randint(1, 10**9), r.randint(1, 10**9))))
Q('Hard', 'GCD LCM', 'Euclid. | Input: a b. | Output: "gcd lcm".', lambda s: '%d %d' % (gcd(*iv(s)), iv(s)[0] * iv(s)[1] // gcd(*iv(s))), [L('12 18')], two(1, 500))
Q('Hard', 'Binary Of N', 'Use strconv.FormatInt(n, 2). | Input: N. | Output: binary.', lambda s: bin(int(s))[2:], [L(10)], num(0, 100000))
Q('Hard', 'Fibonacci Mod', 'F(N) mod 1e9+7 (N<=100000). | Input: N. | Output: value.', lambda s: fibn(int(s)) % (10**9 + 7), [L(10)], num(0, 100000))
Q('Hard', 'Prime Factors', 'Prime factors ascending. | Input: N>=2. | Output: factors.', lambda s: J(pf(int(s))), [L(360)], num(2, 5000))
Q('Hard', 'Nth Prime', 'Print the Nth prime. | Input: N. | Output: prime.', lambda s: [p for p in range(2, 5000) if isp(p)][int(s) - 1], [L(5)], num(1, 200))
Q('Hard', 'Pascal Triangle', 'N rows. | Input: N. | Output: rows.', lambda s: tri(s), [L(4)], num(1, 10))

topic('goslice', 'Slices and Maps', 'append, copy, slicing, sort.Ints, maps and the comma-ok idiom')
Q('Easy', 'Slice Sum', 'Append values and sum. | Input: N, then N integers. | Output: sum.', lambda s: sum(arrs(s)), [L(3, '1 2 3')], Ag)
Q('Easy', 'Slice Max Min', 'Print max and min. | Input: N, then N integers. | Output: "max min".', lambda s: '%d %d' % (max(arrs(s)), min(arrs(s))), [L(3, '4 9 2')], Ag)
Q('Easy', 'Reverse Slice', 'Reverse in place. | Input: N, then N integers. | Output: reversed.', lambda s: J(arrs(s)[::-1]), [L(3, '1 2 3')], Ag)
Q('Easy', 'Sort Ints', 'sort.Ints. | Input: N, then N integers. | Output: sorted.', lambda s: J(sorted(arrs(s))), [L(3, '3 1 2')], Ag)
Q('Easy', 'Len And Cap Idea', 'Print len after appending all values and after slicing [1:]. | Input: N, then N integers. | Output: "n n-1" (n>=1).', lambda s: '%d %d' % (len(arrs(s)), len(arrs(s)) - 1), [L(3, '1 2 3')], Ag)
Q('Easy', 'Count Occurrences Map', 'map[int]int count of X. | Input: N, list, X. | Output: count.', lambda s: iv(s)[1:-1].count(iv(s)[-1]), [L(4, '1 2 1 3', 1)], arq(0, 4, 1, 10, 0, 4))
Q('Easy', 'Distinct Count', 'map[int]bool distinct count. | Input: N, then N integers. | Output: count.', lambda s: len(set(arrs(s))), [L(4, '1 2 2 3')], ar(0, 6, 1, 12))
Q('Medium', 'Filter Evens', 'Build a new slice of evens (or NONE). | Input: N, then N integers. | Output: evens.', lambda s: J(x for x in arrs(s) if x % 2 == 0) or 'NONE', [L(4, '1 2 3 4')], Ag)
Q('Medium', 'Frequency Sorted Keys', 'Print "value:count" with sorted keys. | Input: N, then N integers. | Output: pairs.', lambda s: J('%d:%d' % kv for kv in sorted(Counter(arrs(s)).items())), [L(4, '3 1 3 2')], ar(0, 6, 1, 12))
Q('Medium', 'Remove At Index', 'append(a[:i], a[i+1:]...). | Input: N, list, K. | Output: rest or NONE.', lambda s: (lambda t: (lambda a, k: J(a[:k] + a[k + 1:]) or 'NONE')(t[1:1 + t[0]], t[-1]))(iv(s)), [L(3, '1 2 3', 1)], lambda r: (lambda n: L(n, J([r.randint(0, 9) for _ in range(n)]), r.randint(0, n - 1)))(r.randint(1, 8)))
Q('Medium', 'Two Slices Intersect', 'Sorted common distinct or NONE. | Input: two lines "n values". | Output: common.', lambda s: J(sorted(set(map(int, W(s)[0].split()[1:])) & set(map(int, W(s)[1].split()[1:])))) or 'NONE', [L('3 1 2 3', '2 2 5')], lambda r: L(*[J([k] + [r.randint(0, 6) for _ in range(k)]) for k in (r.randint(1, 5), r.randint(1, 5))]))
Q('Medium', 'Rotate Slice', 'Rotate left by K. | Input: N, list, K. | Output: rotated.', lambda s: (lambda t: (lambda a, k: J(a[k % len(a):] + a[:k % len(a)]))(t[1:1 + t[0]], t[-1]))(iv(s)), [L(5, '1 2 3 4 5', 2)], arq(0, 9, 1, 8, 0, 15))
Q('Medium', '2D Slice Row Sums', 'Row sums. | Input: R C, rows. | Output: sums.', lambda s: J(sum(map(int, l.split())) for l in W(s)[1:]), [L('2 2', '1 2', '3 4')], lambda r: (lambda n, m: L('%d %d' % (n, m)) + ''.join(L(J([r.randint(0, 9) for _ in range(m)])) for _ in range(n)))(r.randint(1, 4), r.randint(1, 4)))
Q('Medium', 'Sort By Struct Field', 'Sort.Slice records "name mark" by mark desc then name. | Input: N, lines. | Output: names.', lambda s: J(l.split()[0] for l in sorted(W(s)[1:], key=lambda l: (-int(l.split()[1]), l.split()[0]))), [L(3, 'b 5', 'a 5', 'c 9')], lambda r: L(*([4] + ['%s %d' % (c, r.randint(0, 3)) for c in 'abcd'])))
Q('Medium', 'Move Zeros', 'Zeros to the end. | Input: N, then N integers. | Output: result.', lambda s: J([x for x in arrs(s) if x] + [0] * arrs(s).count(0)), [L(5, '0 1 0 3 2')], ar(0, 3, 1, 10))
Q('Hard', 'Max Subarray', 'Kadane. | Input: N, then N integers. | Output: sum.', lambda s: kad(arrs(s)), [L(5, '-2 1 -3 4 5')], ar(-9, 9, 1, 12))
Q('Hard', 'Two Sum Indices', 'First pair i<j (nested order) summing to K or NONE. | Input: N, list, K. | Output: "i j".', lambda s: (lambda t: next(('%d %d' % (i, j) for i in range(t[0]) for j in range(i + 1, t[0]) if t[1 + i] + t[1 + j] == t[-1]), 'NONE'))(iv(s)), [L(4, '2 7 11 15', 9)], arq(-5, 12, 2, 9, -5, 15))
Q('Hard', 'Longest Consecutive', 'Longest run of consecutive integers as a set. | Input: N, then N integers. | Output: length.', lambda s: lcr(arrs(s)), [L(6, '100 4 200 1 3 2')], ar(0, 15, 1, 12))
Q('Hard', 'Product Except Self', 'Product of others. | Input: N (>=2), then N integers. | Output: products.', lambda s: J(math.prod(arrs(s)[:i] + arrs(s)[i + 1:]) for i in range(len(arrs(s)))), [L(4, '1 2 3 4')], ar(-3, 4, 2, 7))
Q('Hard', 'Merge Intervals', 'Merge. | Input: N, lines "a b". | Output: merged.', lambda s: mint(W(s)[1:]), [L(3, '1 3', '2 6', '8 10')], lambda r: L(*([5] + [(lambda a: '%d %d' % (a, a + r.randint(0, 5)))(r.randint(0, 15)) for _ in range(5)])))
Q('Hard', 'Subarray Sum K', 'Count subarrays summing to K. | Input: N, list, K. | Output: count.', lambda s: cntsub(iv(s)[1:-1], iv(s)[-1]), [L(4, '1 1 1 2', 2)], arq(-2, 4, 1, 9, -2, 6))
Q('Hard', 'Trap Rain Water', 'Water trapped. | Input: N, heights. | Output: units.', lambda s: rain(arrs(s)), [L(6, '0 2 0 3 0 2')], ar(0, 6, 1, 10))

topic('gostr', 'Strings, Runes and Bytes', 'strings package, strconv, rune iteration and byte slices')
Q('Easy', 'Reverse String', 'Reverse using a rune slice. | Input: a word. | Output: reversed.', lambda s: s.strip()[::-1], [L('abc')], st(1, 12, 'abcxyz'))
Q('Easy', 'Upper And Len', 'strings.ToUpper and len. | Input: a word. | Output: "UP len".', lambda s: '%s %d' % (s.strip().upper(), len(s.strip())), [L('go')], st(1, 12, 'abcxyz'))
Q('Easy', 'Contains Prefix Suffix', 'Print three true/false values: Contains second, HasPrefix, HasSuffix. | Input: text, pattern. | Output: three words.', lambda s: ' '.join(str(x).lower() for x in (W(s)[1] in W(s)[0], W(s)[0].startswith(W(s)[1]), W(s)[0].endswith(W(s)[1]))), [L('hello', 'he')], lambda r: L(''.join(r.choice('ab') for _ in range(r.randint(1, 6))), ''.join(r.choice('ab') for _ in range(r.randint(1, 2)))))
Q('Easy', 'Fields And Join', 'strings.Fields then Join with "-". | Input: a line. | Output: joined.', lambda s: '-'.join(s.split()), [L('a b  c')], wl())
Q('Easy', 'Count Vowels', 'Vowel count. | Input: a line. | Output: count.', lambda s: sum(c in 'aeiouAEIOU' for c in s), [L('Hello World')], lambda r: L(''.join(r.choice('abEiOxyz ') for _ in range(r.randint(1, 15)))))
Q('Easy', 'Atoi And Itoa', 'Parse N, add 1, print as string. | Input: N. | Output: N+1.', lambda s: int(s) + 1, [L(41)], num(-99, 999))
Q('Easy', 'Repeat', 'strings.Repeat(word, N). | Input: word N. | Output: repeated.', lambda s: W(s)[0] * int(W(s)[1]), [L('ab', 3)], lambda r: L(r.choice(['ab', 'x', 'go']), r.randint(1, 6)))
Q('Medium', 'Rune Count Vs Len', 'Print the number of runes and bytes for the line. | Input: text with maybe é or ñ. | Output: "runes bytes".', lambda s: '%d %d' % (len(s.rstrip('\n')), len(s.rstrip('\n').encode())), [L('héllo')], lambda r: L(''.join(r.choice('abé ñ') for _ in range(r.randint(1, 10)))))
Q('Medium', 'Word Frequency Sorted', 'Print "word count" sorted by word. | Input: a line. | Output: rows.', lambda s: '\n'.join('%s %d' % kv for kv in sorted(Counter(s.split()).items())), [L('b a b')], wl(8))
Q('Medium', 'Is Palindrome Phrase', 'Letters only, ignore case: true/false. | Input: a line. | Output: true/false.', lambda s: (lambda t: 'true' if t == t[::-1] else 'false')(''.join(c.lower() for c in s if c.isalpha())), [L('A man, a plan, a canal: Panama')], lambda r: L(r.choice(['A man, a plan, a canal: Panama', 'hello', 'Was it a car or a cat I saw?', 'ab', 'x', 'abca'])))
Q('Medium', 'Replace All', 'strings.ReplaceAll. | Input: text, old, new. | Output: result.', lambda s: W(s)[0].replace(W(s)[1], W(s)[2]), [L('banana', 'an', 'AN')], lambda r: L(''.join(r.choice('ab') for _ in range(r.randint(1, 8))), ''.join(r.choice('ab') for _ in range(r.randint(1, 2))), 'X'))
Q('Medium', 'Title Case', 'Capitalize each word. | Input: a line. | Output: title case.', lambda s: ' '.join(w[0].upper() + w[1:] for w in s.split()), [L('hello big world')], wl())
Q('Medium', 'Anagram Check', 'true/false. | Input: two words. | Output: true/false.', lambda s: 'true' if sorted(W(s)[0]) == sorted(W(s)[1]) else 'false', [L('listen', 'silent')], lambda r: L(*[''.join(r.choice('abc') for _ in range(r.randint(1, 4))) for _ in range(2)]))
Q('Medium', 'Split On Commas', 'Split, TrimSpace each, print one per line. | Input: comma list. | Output: pieces.', lambda s: '\n'.join(p.strip() for p in s.strip().split(',')), [L('a , b,c ')], lambda r: L(', '.join(''.join(r.choice('abc') for _ in range(r.randint(1, 3))) for _ in range(r.randint(1, 4)))))
Q('Medium', 'Byte Frequency', 'Letter counts as "c:n" sorted. | Input: a word. | Output: pairs.', lambda s: J('%s:%d' % kv for kv in sorted(Counter(s.strip()).items())), [L('banana')], st(1, 12, 'abcd'))
Q('Hard', 'Longest Unique Substring', 'Length. | Input: a word. | Output: length.', lambda s: lsr(s.strip()), [L('abcabcbb')], st(1, 14, 'abcd'))
Q('Hard', 'Run Length Encode', 'a3b2. | Input: a word. | Output: encoded.', lambda s: ''.join(k + str(len(list(g))) for k, g in itertools.groupby(s.strip())), [L('aaabbc')], st(1, 12, 'abc'))
Q('Hard', 'Valid Parentheses', 'true/false. | Input: brackets. | Output: true/false.', lambda s: 'true' if bal(s) == 'YES' else 'false', [L('([])')], lambda r: L(''.join(r.choice('()[]{}') for _ in range(r.randint(2, 8)))))
Q('Hard', 'Longest Palindromic Substring', 'Length. | Input: a word. | Output: length.', lambda s: max(j - i for i in range(len(s.strip())) for j in range(i + 1, len(s.strip()) + 1) if s.strip()[i:j] == s.strip()[i:j][::-1]), [L('babad')], st(1, 12, 'ab'))
Q('Hard', 'Add Big Numbers', 'Add two numbers up to 60 digits via math/big or strings. | Input: two numbers. | Output: sum.', lambda s: str(int(W(s)[0]) + int(W(s)[1])), [L('99999999999999999999', 1)], lambda r: L(*[str(r.randint(0, 10**r.randint(1, 60))) for _ in range(2)]))
Q('Hard', 'Decode Ways', 'A=1..Z=26 decodings. | Input: digits. | Output: count.', lambda s: dways(s.strip()), [L('226')], lambda r: L(''.join(r.choice('0123456789') for _ in range(r.randint(1, 10))).lstrip('0') or '1'))
Q('Hard', 'Roman To Int', 'Convert. | Input: numeral. | Output: value.', lambda s: rom(s.strip()), [L('MCMXCIV')], lambda r: L(r.choice(['III', 'IV', 'IX', 'LVIII', 'MCMXCIV', 'XL', 'CD', 'MMXXV', 'XIV'])))

