Q('Hard', 'Inventory', 'add/remove/total. | Input: N, commands. | Output: replies.', lambda s: invq(s), [L(3, 'add a 5', 'remove a 7', 'total')], lambda r: L(*([7] + [r.choice(['add a %d' % r.randint(1, 5), 'add b %d' % r.randint(1, 5), 'remove a %d' % r.randint(1, 6), 'remove b %d' % r.randint(1, 6), 'total']) for _ in range(7)])))
Q('Hard', 'Event Queue', 'time then arrival. | Input: N, "t name". | Output: names.', lambda s: J(l.split()[1] for _, l in sorted(enumerate(W(s)[1:]), key=lambda e: (int(e[1].split()[0]), e[0]))), [L(3, '5 a', '2 b', '5 c')], lambda r: L(*([5] + ['%d %s' % (r.randint(0, 4), c) for c in 'abcde'])))
