topic('goalg', 'Algorithms and Concurrency', 'recursion, sorting, graphs, dynamic programming and goroutines with channels')
Q('Easy', 'Factorial', 'Recursive. | Input: N (<=20). | Output: N!.', lambda s: fact(int(s)), [L(5)], num(0, 20))
Q('Easy', 'Fibonacci', 'Iterative. | Input: N (<=90). | Output: F(N).', lambda s: fibn(int(s)), [L(50)], num(0, 90))
Q('Easy', 'Goroutine Sum Halves', 'Sum two halves of the array in two goroutines using a channel and print the total. | Input: N, then N integers. | Output: sum.', lambda s: sum(arrs(s)), [L(4, '1 2 3 4')], Ag)
Q('Easy', 'Linear Search', 'First index or -1. | Input: N, list, X. | Output: index.', lambda s: (lambda t: (lambda a, x: a.index(x) if x in a else -1)(t[1:1 + t[0]], t[-1]))(iv(s)), [L(3, '4 5 6', 5)], arq(0, 9, 1, 8, 0, 9))
Q('Easy', 'Power Recursive', 'a^b. | Input: a b. | Output: a^b.', lambda s: iv(s)[0] ** iv(s)[1], [L('2 8')], lambda r: L('%d %d' % (r.randint(0, 5), r.randint(0, 9))))
Q('Easy', 'Bubble Sort', 'Sort. | Input: N, then N integers. | Output: sorted.', lambda s: J(sorted(arrs(s))), [L(3, '3 1 2')], Ag)
