Q('Medium', 'Binary Search', 'Index or -1. | Input: N, sorted list, X. | Output: index.', lambda s: (lambda t: (lambda a, x: a.index(x) if x in a else -1)(t[1:1 + t[0]], t[-1]))(iv(s)), [L(4, '1 3 5 7', 5)], lambda r: (lambda n: L(n, J(sorted(r.sample(range(0, 30), n))), r.randint(0, 30)))(r.randint(1, 8)))
Q('Medium', 'Climbing Stairs', 'Ways with 1 or 2 steps. | Input: N. | Output: ways.', lambda s: fibn(int(s) + 1), [L(5)], num(1, 40))
Q('Medium', 'Coin Change Min', 'Min coins or -1. | Input: K, coins, T. | Output: min.', lambda s: coinmin(iv(s)), [L(3, '1 2 5', 11)], lambda r: (lambda k: L(k, J(r.sample(range(1, 9), k)), r.randint(0, 25)))(r.randint(1, 4)))
Q('Medium', 'Merge Sorted Slices', 'Merge. | Input: two lines "n values". | Output: merged.', lambda s: J(sorted(sum((list(map(int, l.split()))[1:] for l in W(s)), []))), [L('2 1 4', '2 2 3')], lambda r: L(*[J([k] + sorted(r.randint(0, 20) for _ in range(k))) for k in (r.randint(1, 5), r.randint(1, 5))]))
Q('Medium', 'Pipeline Channels', 'Stage 1 doubles, stage 2 adds 1 via channels; print results in order. | Input: N, then N integers. | Output: results.', lambda s: J(x * 2 + 1 for x in arrs(s)), [L(3, '1 2 3')], Ag)
