Q('Hard', 'LCS Length', 'Length. | Input: two words. | Output: length.', lambda s: lcs(*W(s)), [L('abcde', 'ace')], lambda r: L(*[''.join(r.choice('abc') for _ in range(r.randint(1, 8))) for _ in range(2)]))
Q('Hard', 'Edit Distance', 'Levenshtein. | Input: two words. | Output: distance.', lambda s: ed(*W(s)), [L('kitten', 'sitting')], lambda r: L(*[''.join(r.choice('abc') for _ in range(r.randint(1, 7))) for _ in range(2)]))
Q('Hard', 'N Queens', 'Count. | Input: N (<=8). | Output: count.', lambda s: nq(int(s)), [L(4)], num(1, 8))
